//! Generated TypeScript shims for opencode and Pi (SPEC 6.11, ADR 0025).
//!
//! The templates in `shims/` are the only TypeScript tokenimum ships. Each
//! generated file starts with a two-line header naming tokenimum, its version
//! and a SHA-256 over every byte after the header, so `tkm doctor` can detect
//! edits and `tkm uninstall` removes only files it can prove it generated.

use crate::{AdapterError, digest, writer};
use serde_json::Value;
use sha2::{Digest, Sha256};
use std::{
    fs,
    io::{self, Write},
    path::{Component, Path, PathBuf},
    sync::atomic::{AtomicU64, Ordering},
};
use tkm_proto::{Host, ReplyAction};

const OPENCODE: &str = include_str!("../../../shims/opencode.ts");
const PI: &str = include_str!("../../../shims/pi.ts");
const HEADER_SUFFIX: &str = " shim. Generated by tkm init; do not edit.";
const HASH_PREFIX: &str = "// tokenimum-sha256: ";
const REPLY_CAP: usize = 10_000;

/// Result of checking a file against the shim header contract.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ShimStatus {
    /// Header parses and the hash matches the body: tokenimum generated this file.
    Ok,
    /// Header parses but the body hash differs: someone edited the file.
    HashMismatch,
    /// No tokenimum shim header: a foreign file.
    NotOurs,
}

fn hex_sha256(bytes: &[u8]) -> String {
    const DIGITS: &[u8; 16] = b"0123456789abcdef";
    let mut out = String::with_capacity(64);
    for byte in Sha256::digest(bytes).iter() {
        out.push(char::from(DIGITS[usize::from(byte >> 4)]));
        out.push(char::from(DIGITS[usize::from(byte & 15)]));
    }
    out
}

/// Splits off the two header lines; the body keeps every later byte.
fn split_header(bytes: &[u8]) -> Option<(&[u8], &[u8], &[u8])> {
    let first = bytes.iter().position(|byte| *byte == b'\n')?;
    let rest = &bytes[first + 1..];
    let second = rest.iter().position(|byte| *byte == b'\n')?;
    Some((&bytes[..first], &rest[..second], &rest[second + 1..]))
}

/// Parses the header, returning `(version, host name, hash, body)`.
fn parse(bytes: &[u8]) -> Option<(&str, &str, &str, &[u8])> {
    let (first, second, body) = split_header(bytes)?;
    let first = std::str::from_utf8(first).ok()?;
    let second = std::str::from_utf8(second).ok()?;
    let middle = first
        .strip_prefix("// tokenimum ")?
        .strip_suffix(HEADER_SUFFIX)?;
    let (version, host) = middle.split_once(' ')?;
    let hash = second.strip_prefix(HASH_PREFIX)?;
    let hex = hash.len() == 64 && hash.bytes().all(|b| matches!(b, b'0'..=b'9' | b'a'..=b'f'));
    (!version.is_empty() && matches!(host, "opencode" | "pi") && hex)
        .then_some((version, host, hash, body))
}

/// Renders the shim for `host`, stamping `version` and the body hash.
///
/// # Errors
/// Returns [`AdapterError::Unsupported`] for hosts without a shim, and
/// [`AdapterError::InvalidPayload`] when `version` contains whitespace.
pub fn render(host: Host, version: &str) -> Result<Vec<u8>, AdapterError> {
    let template = match host {
        Host::Opencode => OPENCODE,
        Host::Pi => PI,
        _ => {
            return Err(AdapterError::Unsupported {
                operation: format!("shim for {}", host.as_str()),
            });
        }
    };
    if version.is_empty() || version.chars().any(|c| c.is_whitespace() || c.is_control()) {
        return Err(writer::invalid("shim version must be a single token"));
    }
    let malformed = || AdapterError::Unsupported {
        operation: "shim template header".to_owned(),
    };
    let (first, second, body) = split_header(template.as_bytes()).ok_or_else(malformed)?;
    let first = std::str::from_utf8(first)
        .map_err(|_| malformed())?
        .replace("{{VERSION}}", version);
    let second = std::str::from_utf8(second)
        .map_err(|_| malformed())?
        .replace("{{HASH}}", &hex_sha256(body));
    let mut out = Vec::with_capacity(template.len() + 64);
    out.extend_from_slice(first.as_bytes());
    out.push(b'\n');
    out.extend_from_slice(second.as_bytes());
    out.push(b'\n');
    out.extend_from_slice(body);
    Ok(out)
}

/// Checks `bytes` against the header and body hash.
#[must_use]
pub fn verify_shim(bytes: &[u8]) -> ShimStatus {
    match parse(bytes) {
        None => ShimStatus::NotOurs,
        Some((_, _, hash, body)) if hash == hex_sha256(body) => ShimStatus::Ok,
        Some(_) => ShimStatus::HashMismatch,
    }
}

fn refuse(path: &Path, reason: &str) -> AdapterError {
    AdapterError::UnsafeTarget {
        path: path.to_path_buf(),
        reason: reason.to_owned(),
    }
}

fn read_existing(path: &Path) -> Result<Option<Vec<u8>>, AdapterError> {
    match fs::read(path) {
        Ok(bytes) => Ok(Some(bytes)),
        Err(error) if error.kind() == io::ErrorKind::NotFound => Ok(None),
        Err(error) => Err(error.into()),
    }
}

/// Status of an existing file as a shim of `host`; other hosts' shims are foreign.
fn status_for(host: Host, bytes: &[u8]) -> ShimStatus {
    match parse(bytes) {
        Some((_, name, _, _)) if name == host.as_str() => verify_shim(bytes),
        _ => ShimStatus::NotOurs,
    }
}

fn write_atomic(target: &Path, bytes: &[u8]) -> Result<(), AdapterError> {
    static NEXT: AtomicU64 = AtomicU64::new(0);
    let parent = target
        .parent()
        .ok_or_else(|| refuse(target, "target has no parent"))?;
    fs::create_dir_all(parent)?;
    let (temporary, mut file) = loop {
        let temporary = parent.join(format!(
            ".tkm-{}-{}.tmp",
            std::process::id(),
            NEXT.fetch_add(1, Ordering::Relaxed)
        ));
        match fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&temporary)
        {
            Ok(file) => break (temporary, file),
            Err(error) if error.kind() == io::ErrorKind::AlreadyExists => {}
            Err(error) => return Err(error.into()),
        }
    };
    let result = (|| -> Result<(), AdapterError> {
        if let Ok(metadata) = fs::metadata(target) {
            file.set_permissions(metadata.permissions())?;
        }
        file.write_all(bytes)?;
        file.sync_all()?;
        fs::rename(&temporary, target)?;
        Ok(())
    })();
    if result.is_err() {
        let _ = fs::remove_file(&temporary);
    }
    result
}

/// Installs or upgrades the shim at `path`, which must lie inside `root`.
///
/// Returns the changed files (empty when already current). An edited shim or
/// a foreign file at `path` is refused and left untouched.
pub(crate) fn install(
    host: Host,
    root: &Path,
    path: &Path,
    dry_run: bool,
) -> Result<Vec<PathBuf>, AdapterError> {
    let bytes = render(host, env!("CARGO_PKG_VERSION"))?;
    let target = writer::safe_target(root, path)?;
    if let Some(current) = read_existing(&target)? {
        match status_for(host, &current) {
            ShimStatus::Ok if current == bytes => return Ok(Vec::new()),
            ShimStatus::Ok => {}
            ShimStatus::HashMismatch => {
                return Err(refuse(path, "shim was edited; refusing to overwrite it"));
            }
            ShimStatus::NotOurs => {
                return Err(refuse(
                    path,
                    "file is not a tokenimum shim; refusing to overwrite it",
                ));
            }
        }
    }
    if !dry_run {
        write_atomic(&target, &bytes)?;
    }
    Ok(vec![path.to_path_buf()])
}

/// Removes the shim at `path` only when its header parses and the hash verifies.
///
/// A foreign file is left alone and reported as unchanged; an edited shim is
/// refused with an error.
pub(crate) fn uninstall(
    host: Host,
    root: &Path,
    path: &Path,
    dry_run: bool,
) -> Result<Vec<PathBuf>, AdapterError> {
    let target = writer::safe_target(root, path)?;
    let Some(current) = read_existing(&target)? else {
        return Ok(Vec::new());
    };
    match status_for(host, &current) {
        ShimStatus::Ok => {}
        ShimStatus::HashMismatch => {
            return Err(refuse(path, "shim was edited; refusing to remove it"));
        }
        ShimStatus::NotOurs => return Ok(Vec::new()),
    }
    if !dry_run {
        fs::remove_file(&target)?;
    }
    Ok(vec![path.to_path_buf()])
}

/// Renders the shared shim reply: compact `{"context":..,"notice":..}`.
///
/// Parts the event does not allow, and empty parts, are dropped; nothing to
/// deliver renders as the empty string. Text is capped at 10,000 characters.
pub(crate) fn reply_json(action: &ReplyAction, inject_ok: bool, notice_ok: bool) -> String {
    let (inject, notice) = match action {
        ReplyAction::Inject { text } => (Some(text), None),
        ReplyAction::Notice { text } => (None, Some(text)),
        ReplyAction::InjectAndNotice { inject, notice } => (Some(inject), Some(notice)),
        _ => (None, None),
    };
    let mut parts = Vec::new();
    for (key, text, allowed) in [
        ("context", inject, inject_ok),
        ("notice", notice, notice_ok),
    ] {
        if allowed && let Some(text) = text.filter(|text| !text.is_empty()) {
            let text = Value::String(digest::truncate(text, REPLY_CAP));
            parts.push(format!("\"{key}\":{text}"));
        }
    }
    if parts.is_empty() {
        String::new()
    } else {
        format!("{{{}}}", parts.join(","))
    }
}

fn normalized(path: &Path) -> Option<PathBuf> {
    let mut result = PathBuf::new();
    for component in path.components() {
        match component {
            Component::CurDir => {}
            Component::ParentDir => {
                if !result.pop() {
                    return None;
                }
            }
            _ => result.push(component.as_os_str()),
        }
    }
    Some(result)
}

/// Returns `file` relative to `cwd` when it lies strictly inside it.
pub(crate) fn repo_relative(cwd: &Path, file: &str) -> Option<PathBuf> {
    let cwd = normalized(cwd)?;
    let file = Path::new(file);
    let file = if file.is_absolute() {
        file.to_path_buf()
    } else {
        cwd.join(file)
    };
    let relative = normalized(&file)?.strip_prefix(&cwd).ok()?.to_path_buf();
    let inside = !relative.as_os_str().is_empty()
        && relative
            .components()
            .all(|component| matches!(component, Component::Normal(_)));
    inside.then_some(relative)
}
